package com.google.javascript.rhino.jstype;

import com.google.common.collect.Maps;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.jstype.JSTypeNative;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class RecordTypeBuilder_build_TriageGen1Test {

    private JSTypeRegistry registry;

    @Before
    public void setUp() {
        registry = new JSTypeRegistry();
    }

    @Test
    public void testBuild_withEmptyProperties_returnsObjectType() {
        // Arrange
        RecordTypeBuilder builder = new RecordTypeBuilder(registry);

        // Act
        JSType result = builder.build();

        // Assert
        // When isEmpty is true, it returns the native OBJECT_TYPE
        assertEquals(JSTypeNative.OBJECT_TYPE, result);
    }

    @Test
    public void testBuild_withProperties_returnsRecordType() {
        // Arrange
        RecordTypeBuilder builder = new RecordTypeBuilder(registry);
        String propName = "testProp";
        JSType propType = registry.getNativeObjectType(JSTypeNative.STRING_TYPE);
        Node propNode = new Node(com.google.javascript.rhino.Token.NAME, propName);

        builder.addProperty(propName, propType, propNode);

        // Act
        JSType result = builder.build();

        // Assert
        assertTrue("Result should be an instance of RecordType", result instanceof RecordType);

        RecordType recordType = (RecordType) result;
        Map<String, JSType> properties = recordType.getProperties();

        assertEquals(1, properties.size());
        assertTrue(properties.containsKey(propName));
        assertEquals(propType, properties.get(propName));
    }

    @Test
    public void testBuild_multipleProperties_returnsRecordTypeWithAllProperties() {
        // Arrange
        RecordTypeBuilder builder = new RecordTypeBuilder(registry);

        String name1 = "name";
        JSType type1 = registry.getNativeObjectType(JSTypeNative.STRING_TYPE);
        Node node1 = new Node(com.google.javascript.rhino.Token.NAME, name1);

        String name2 = "age";
        JSType type2 = registry.getNativeObjectType(JSTypeNative.NUMBER_TYPE);
        Node node2 = new Node(com.google.javascript.rhino.Token.NAME, name2);

        builder.addProperty(name1, type1, node1);
        builder.addProperty(name2, type2, node2);

        // Act
        JSType result = builder.build();

        // Assert
        assertTrue(result instanceof RecordType);
        RecordType recordType = (RecordType) result;
        Map<String, JSType> properties = recordType.getProperties();

        assertEquals(2, properties.size());
        assertEquals(type1, properties.get(name1));
        assertEquals(type2, properties.get(name2));
    }
}
